#!/bin/bash
# Uninstall script for yWorks yEd
# Generated by IntuneBrew

# Exit on error
set -e

echo "Uninstalling yWorks yEd..."

# Check if running as root
if [ "$EUID" -ne 0 ]; then
  echo "Please run as root"
  exit 1
fi

# Kill application process if running
echo "Stopping yWorks yEd if running..."
pkill -f "yWorks yEd" 2>/dev/null || true

# Remove /Applications/yEd.app
echo "Removing /Applications/yEd.app..."
if [ -d "/Applications/yEd.app" ]; then
    rm -rf "/Applications/yEd.app" 2>/dev/null || true
elif [ -f "/Applications/yEd.app" ]; then
    rm -f "/Applications/yEd.app" 2>/dev/null || true
fi

# Remove $HOME/Library/Saved Application State/com.yworks.yEd.savedState
echo "Removing $HOME/Library/Saved Application State/com.yworks.yEd.savedState..."
if [ -d "$HOME/Library/Saved Application State/com.yworks.yEd.savedState" ]; then
    rm -rf "$HOME/Library/Saved Application State/com.yworks.yEd.savedState" 2>/dev/null || true
elif [ -f "$HOME/Library/Saved Application State/com.yworks.yEd.savedState" ]; then
    rm -f "$HOME/Library/Saved Application State/com.yworks.yEd.savedState" 2>/dev/null || true
fi

# Remove $HOME/Library/yWorks/yEd
echo "Removing $HOME/Library/yWorks/yEd..."
if [ -d "$HOME/Library/yWorks/yEd" ]; then
    rm -rf "$HOME/Library/yWorks/yEd" 2>/dev/null || true
elif [ -f "$HOME/Library/yWorks/yEd" ]; then
    rm -f "$HOME/Library/yWorks/yEd" 2>/dev/null || true
fi

echo "Uninstallation complete!"
exit 0
